def plan(sid,rows,background):
    author(sid,rows)
    ep=ROOT/'studio/episodes'/sid;p=ep/'script.yaml';d=yaml.safe_load(p.read_text());d['render']['palette']=PALETTE;d['asset_requests'][0]['description']=background
    for item in d['episode_decisions']:item['decision']=item['decision'].replace('Chapter10oceanpalette','Chapter 11 moss palette')
    for r in d['sentences']:r['pronunciation_notes']=['Swedish source words and source numbers require complete-video listening; ASR remains diagnostic.']
    p.write_text(yaml.safe_dump(d,allow_unicode=True,sort_keys=False,width=100))

